command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: KÖDER (Ausführung mit Sicherheits-Timer)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Köder";
    const ahne = "Rondra";
    const finalEffektName = `${gabenName} (${ahne})`;
    const zielEffektName = "Köder";
    const iconBild = DSK_FW.Symbol(ahne);

    // --- 2. KÖDER KONFIGURATION & FRAMEWORK REGISTRIERUNG ---
    const koederEintraege = ["@UUID[Actor.c0syFFOoG2sLL02H]{Rondras Köder}"];
    const koederNamen = ["Rondras Köder"];
    const koederHtml = koederEintraege.map(k => `<li>${k}</li>`).join("");

    if (DSK_FW.SpawnSystem && typeof DSK_FW.SpawnSystem.RegisterSpawn === "function") {
        DSK_FW.SpawnSystem.RegisterSpawn(
            finalEffektName, 
            zielEffektName, 
            koederNamen, 
            ahne, 
            "Dieses Wesen ist als Köder aktiv und zieht Feinde auf sich."
        );
    }

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("rondraKoeder", finalEffektName, "Der Köder zerfällt wieder zu gewöhnlicher Erde.");
    }

    // 🚩 DAS NEUE SICHERHEITS-NETZ: Wartet nach dem Platzieren und korrigiert!
    if (!globalThis.DSK_KoederSpawnSicherheit) {
        globalThis.DSK_KoederSpawnSicherheit = true;
        Hooks.on("createToken", (tokenDoc, options, userId) => {
            if (game.user.id !== userId) return; 

            // Reagiert nur, wenn wirklich ein "Rondras Köder" platziert wurde
            if (koederNamen.includes(tokenDoc.name)) {
                // Warte 800ms, damit Foundry den Token fertig geladen hat
                setTimeout(async () => {
                    const tokenActor = tokenDoc.actor;
                    if (!tokenActor) return;

                    // Finde alle Köder-Effekte auf dem Token
                    const effekte = tokenActor.effects.filter(e => (e.name || e.label) === zielEffektName);

                    // ZU VIELE EFFEKTE? -> Alle bis auf den allerersten löschen
                    if (effekte.length > 1) {
                        for (let i = 1; i < effekte.length; i++) {
                            await effekte[i].delete();
                        }
                    } 
                    // GAR KEIN EFFEKT? -> Den Effekt sicher von Hand anlegen
                    else if (effekte.length === 0) {
                        await tokenActor.createEmbeddedDocuments("ActiveEffect", [{
                            name: zielEffektName,
                            icon: iconBild,
                            img: iconBild,
                            description: "Dieses Wesen ist als Köder aktiv und zieht Feinde auf sich.",
                            flags: { dsk: { ahne: ahne } }
                        }]);
                    }
                }, 800);
            }
        });
    }

    // --- 3. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    // --- 4. PRÜFUNG: IST DER WIRKENDE ERWACHT? ---
    if (DSK_FW.Wesen && !DSK_FW.Wesen.match(casterActor, ["erwacht", "erwachter", "erwachte"])) {
        const infoHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b style="font-size: 1.05em;">Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; text-align: center;">
                    <p style="margin-bottom: 8px;"><b>${casterActor.name}</b> ist kein Erwachter.</p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b> Die Gabe kann nur von Erwachten gewirkt werden.</p>
                </div>
            </div>
        `;
        let whisperTo = game.users.filter(u => u.isGM).map(u => u.id);
        const owners = Object.entries(casterActor.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
        whisperTo = [...new Set([...whisperTo, ...owners])].filter(id => game.users.get(id));

        await ChatMessage.create({ whisper: whisperTo, speaker: { alias: "System" }, content: infoHtml });
        return;
    }

    // --- 5. BERECHNUNGEN & EFFEKT ANWENDEN ---
    const dauerMinuten = qsWert;

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    let alterEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffekt) await alterEffekt.delete();

    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { minutes: dauerMinuten },
        description: `Hat einen Köder erschaffen, der sich mit GS 3 wegbewegt.`,
        flags: { dsk: { ahne: ahne, casterUuid: casterActor.uuid } }
    }]);

    // --- 6. CHAT NACHRICHT GENERIEREN ---
    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> gibt etwas aufgehobener Erde grob die Form eines kleinen Tieres.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px; font-size: 0.9em;">
                    Durch die Gabe nimmt es das Aussehen eines lebenden Tieres an und bewegt sich mit <b>GS 3</b> vom Rondrakind weg in eine von diesem gewählte Richtung.
                </p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;"><b>Verfügbarer Köder:</b></p>
                <ul class="dsklist" style="margin-top:0;">
                    ${koederHtml}
                </ul>
                <p style="font-size: 0.85em; color: #555; text-align:center; margin-top:5px;"><i>(Ziehe den Köder auf die Karte)</i></p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(${qsWert} QS)</span></p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent });
    } else {
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
